const payload = JSON.parse($input.first().json.payload);
const size = payload.chunk_size || 180;
function chunkFixed(text, size, overlap) {
  const chunks = []; let i = 0;
  while (i < text.length) {
    const end = Math.min(i + size, text.length);
    chunks.push({start: i, end: end, text: text.slice(i, end)});
    if (end === text.length) break;
    i += size - overlap;
  }
  return chunks;
}
function answerIntact(chunks, aStart, aEnd) {
  for (const c of chunks) { if (c.start <= aStart && aEnd <= c.end) return true; }
  return false;
}
const chunks = chunkFixed(payload.document, size, 0);
const aStart = payload.answer_start;
const aEnd = aStart + payload.answer.length;
const intact = answerIntact(chunks, aStart, aEnd);
return [{json: {...payload, chunk_size: size, chunks_v1: chunks, v1_intact: intact}}];

const d = $input.first().json;
function chunkStructural(text, target) {
  const sentences = text.split(/(?<=[.!?])\s+/);
  const chunks = []; let pos = 0, curStart = 0, curText = '';
  for (const sent of sentences) {
    let idx = text.indexOf(sent, pos); if (idx === -1) idx = pos;
    const sStart = idx, sEnd = idx + sent.length;
    if (curText && (curText.length + sent.length + 1 > target)) {
      chunks.push({start: curStart, end: pos, text: curText});
      curText = sent; curStart = sStart;
    } else {
      if (!curText) curStart = sStart;
      curText = curText ? (curText + ' ' + sent).trim() : sent;
    }
    pos = sEnd;
  }
  if (curText) chunks.push({start: curStart, end: text.length, text: curText});
  return chunks;
}
function answerIntact(chunks, aStart, aEnd) {
  for (const c of chunks) { if (c.start <= aStart && aEnd <= c.end) return true; }
  return false;
}
const chunks = chunkStructural(d.document, d.chunk_size);
const aStart = d.answer_start;
const aEnd = aStart + d.answer.length;
const intact = answerIntact(chunks, aStart, aEnd);
return [{json: {...d, chunks_v2: chunks, v2_intact: intact}}];

